code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    segments = []
    for r in range(h):
        for c in range(w):
            if g[r][c] != 5 or (r, c) in seen:
                continue
            # Collect a straight contiguous run of 5s, using the dominant axis.
            left = c
            while left > 0 and g[r][left - 1] == 5:
                left -= 1
            right = c
            while right + 1 < w and g[r][right + 1] == 5:
                right += 1
            top = r
            while top > 0 and g[top - 1][c] == 5:
                top -= 1
            bottom = r
            while bottom + 1 < h and g[bottom + 1][c] == 5:
                bottom += 1
            if right - left >= bottom - top:
                cells = [(r, x) for x in range(left, right + 1)]
                orient = 'H'
            else:
                cells = [(y, c) for y in range(top, bottom + 1)]
                orient = 'V'
            for cell in cells:
                seen.add(cell)
            segments.append((orient, cells))

    for orient, cells in segments:
        if orient == 'V':
            col = cells[0][1]
            r0, r1 = cells[0][0], cells[-1][0]
            # The colored pattern to the right of a vertical 5-line is repeated along it.
            template_rows = []
            for r in range(h):
                if any(g[r][c] not in (0, 5) for c in range(col + 1, w)):
                    template_rows.append(r)
            if template_rows:
                templates = [[g[r][c] for c in range(col + 1, w)] for r in template_rows]
                for i, r in enumerate(range(r0, r1 + 1)):
                    for j, value in enumerate(templates[i % len(templates)], start=col + 1):
                        if value != 0 and g[r][j] == 0:
                            g[r][j] = value
        else:
            row = cells[0][0]
            c0, c1 = cells[0][1], cells[-1][1]
            # A vertical color sequence below a horizontal 5-line is copied across it.
            source_cols = [c for c in range(c0, c1 + 1)
                           if any(g[r][c] not in (0, 5) for r in range(row + 1, h))]
            if source_cols:
                src = source_cols[0]
                for r in range(row + 1, h):
                    value = g[r][src]
                    if value not in (0, 5):
                        for c in range(c0, c1 + 1):
                            if g[r][c] == 0:
                                g[r][c] = value
    return g
